export type DeskView = 'manage' | 'events' | 'map';

export interface DeskFilters {
    date?: number;
    zones?: string[];
    search?: string;
    view?: DeskView;
}

export interface DeskQrItem {
    id: string;
    name?: string;
    qr_code?: string;
    qr_link?: string;
}

/** Booking fields that the desk bookings search matches. */
export const DESK_BOOKING_SEARCH_KEYS = [
    'user_name',
    'asset_name',
    'user_email',
    'asset_id',
    'status',
    'group',
    'title',
];

/**
 * True when the booking matches the search text. Uses the same rule as the
 * bookings table filter, so bulk actions only affect the rows on screen.
 */
export function matchesDeskSearch(booking: Booking, search?: string) {
    const text = search?.toLowerCase();
    if (!text) return true;
    return rowSearchText(booking, DESK_BOOKING_SEARCH_KEYS).includes(text);
}

@Injectable({
    providedIn: 'root',
})
export class DesksStateService extends AsyncHandler {
    private _org = inject(OrganisationService);
    private _dialog = inject(MatDialog);
    private _settings = inject(SettingsService);

    private _filters = signal<DeskFilters>({});
    private _loading = signal<boolean>(false);
    private _change = signal(0);
    private _booking_status = signal<Record<string, 'approved' | 'declined'>>(
        {},
    );

    public readonly loading = this._loading.asReadonly();
    /**
     * True from a date or level change until the first page for the new
     * filters loads. The bookings on screen are stale until then.
     */
    private readonly _filters_changed = signal(false);
    public readonly filters_changed = this._filters_changed.asReadonly();
    private readonly _load_error = signal(false);
    /** Whether the latest load of bookings failed */
    public readonly load_error = this._load_error.asReadonly();
    public readonly filters = this._filters.asReadonly();
    public readonly print_desk = signal<DeskQrItem | null>(null);

    public get tz_offset() {
        const tz = this._settings.get('app.bookings.use_building_timezone')
            ? this._org.building.timezone
            : '';
        const current_tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
        return !tz ? 0 : getTimezoneDifferenceInHours(current_tz, tz);
    }

    /**
     * Inputs that affect the desk metadata listing. Search is intentionally
     * excluded — it is applied client side and must not trigger a reload.
     */
    private readonly _desk_params = computed(
        () => ({
            view: this._filters().view,
            zones: this._filters().zones || [],
            change: this._change(),
            building: this._org.active_building()?.id,
            region: this._org.active_region()?.id,
            use_assets: !!this._settings.get('app.desks.use_assets'),
        }),
        {
            equal: (a, b) =>
                a.view === b.view &&
                a.change === b.change &&
                a.building === b.building &&
                a.region === b.region &&
                a.use_assets === b.use_assets &&
                a.zones.join(',') === b.zones.join(','),
        },
    );
    private readonly _desk_params_debounced = debounced(this._desk_params, 300);

    /** List of desks for the active management levels */
    private readonly _desks = resource({
        params: () => this._desk_params_debounced.value(),
        defaultValue: [] as Desk[],
        loader: async ({ params }) => {
            if (params.view !== 'manage' && params.view !== 'events') return [];
            this._loading.set(true);
            try {
                const zones = this._getActiveZones(params.zones);
                if (params.use_assets) {
                    const levels = new Map(
                        this._currentLevelList().map((level) => [
                            level.id,
                            level,
                        ]),
                    );
                    // all levels are one query for the building or region
                    const assets =
                        zones.length && !params.zones.includes('All')
                            ? await queryDeskAssetsForZones(zones)
                            : await queryDeskAssetsInZone(
                                  this._currentScopeId(),
                              );
                    return assets
                        .map((asset) =>
                            deskFromAsset(asset, levels.get(asset.zone_id)),
                        )
                        .sort((a, b) => a.name.localeCompare(b.name));
                }
                let list: any[] = [];
                if (zones.length && !params.zones.includes('All')) {
                    const metadata = await Promise.all(
                        zones.map(async (zone) => ({
                            zone,
                            details: await showMetadata(zone, 'desks')
                                .then((item) =>
                                    item.details instanceof Array
                                        ? item.details
                                        : [],
                                )
                                .catch(() => []),
                        })),
                    );
                    list = metadata.flatMap(({ zone, details }) =>
                        details.map((item) => ({
                            ...item,
                            zone: { id: zone },
                        })),
                    );
                } else {
                    const metadata = await listChildMetadata(
                        this._org.building?.id,
                        { name: 'desks' },
                    ).catch(() => [] as unknown[]);
                    // Tag each desk with its level so per-desk saves can
                    // target the correct zone when viewing all levels.
                    list = metadata
                        .map((item) =>
                            (item.metadata?.desks?.details instanceof Array
                                ? item.metadata.desks.details
                                : []
                            ).map((i) => ({ ...i, zone: item.zone })),
                        )
                        .reduce(
                            (c: unknown[], i: unknown[]) => [...c, ...i],
                            [],
                        );
                }
                if (!(list instanceof Array)) list = [];
                list.sort((a, b) => a.name?.localeCompare(b.name));
                return list.map((i) => new Desk({ ...i, qr_code: '' }));
            } finally {
                this._loading.set(false);
            }
        },
    });
    public readonly desks: Signal<Desk[]> = this._desks.value;

    /** List of levels with bookable desk resources */
    private readonly _levels = resource({
        params: () => ({
            levels: this._org.active_levels(),
            use_assets: !!this._settings.get('app.desks.use_assets'),
        }),
        defaultValue: [] as BuildingLevel[],
        loader: async ({ params: { levels, use_assets } }) => {
            if (!levels.length) return [];
            const results = await Promise.all(
                levels.map(async (level) => {
                    if (use_assets) {
                        const desks = await queryDeskAssets(level.id).catch(
                            () => [],
                        );
                        return {
                            level,
                            has_bookable: desks.some((desk) => desk.bookable),
                        };
                    }
                    const metadata = await showMetadata(
                        level.id,
                        'desks',
                    ).catch(() => null);
                    return {
                        level,
                        has_bookable:
                            metadata?.details instanceof Array &&
                            metadata.details.some((desk) => desk.bookable),
                    };
                }),
            );
            return results
                .filter((item) => item.has_bookable)
                .map((item) => item.level);
        },
    });
    public readonly levels: Signal<BuildingLevel[]> = this._levels.value;

    /** Accumulated paged desk bookings for the events view */
    private readonly _bookings_state = signal<{
        list: Booking[];
        total: number;
        has_next: boolean;
    }>({ list: [], total: 0, has_next: false });
    public readonly paged_bookings = this._bookings_state.asReadonly();

    public readonly has_more_pages = computed(
        () => this.paged_bookings().has_next,
    );
    public readonly bookings = computed(() => {
        const desks = new Map(this.desks().map((desk) => [desk.id, desk]));
        // bookings that predate desk assets reference the original desk id
        const place_desks = new Map(
            this.desks()
                .filter((desk) => desk['place_id'])
                .map((desk) => [desk['place_id'] as string, desk]),
        );
        const map_desks = new Map(
            this.desks().map((desk) => [desk.map_id || desk.id, desk]),
        );
        const bookings = this.paged_bookings().list;
        for (const booking of bookings) {
            const desk =
                desks.get(booking.asset_id) ||
                place_desks.get(booking.asset_id) ||
                map_desks.get(booking.asset_id);
            Object.assign(booking, {
                asset_name: desk?.name || booking.asset_id,
            });
        }
        return [...bookings];
    });
    /** Time the booking list last finished loading from the server */
    private readonly _last_updated = signal(0);
    public readonly last_updated = this._last_updated.asReadonly();

    /** Query for the first page of bookings for the active filters */
    private _first_page: (() => QueryResponse<Booking>) | null = null;
    /** Query for the next page of bookings */
    private _next_page_fn: (() => QueryResponse<Booking> | null) | null = null;
    /** Token used to discard responses from superseded page loads */
    private _load_token = 0;
    private _all_zones_keys = ['All', -1, '-1', ''];
    private readonly _bookings_params = computed(
        () => ({
            filters: this._filters(),
            loaded: this._org.initialised(),
            building: this._org.active_building()?.id,
            region: this._org.active_region()?.id,
        }),
        {
            equal: (a, b) =>
                a.loaded === b.loaded &&
                a.building === b.building &&
                a.region === b.region &&
                a.filters.view === b.filters.view &&
                a.filters.date === b.filters.date &&
                (a.filters.zones || []).join(',') ===
                    (b.filters.zones || []).join(','),
        },
    );
    private readonly _bookings_params_debounced = debounced(
        this._bookings_params,
        500,
    );

    /** Append the next page of bookings. Resolves when the page loads. */
    public nextPage() {
        return this._loadPage(false);
    }

    constructor() {
        super();
        // Rebuild the paging query whenever the filters, organisation or
        // initialised state change. Debounced to collapse rapid updates.
        effect(() => {
            const { filters, loaded } = this._bookings_params_debounced.value();
            // Only load bookings when on events view
            if (!loaded || filters.view !== 'events') return;
            this._first_page = this._buildFirstPage(filters);
            this._next_page_fn = this._first_page;
            this._loadPage(true);
        });
    }

    /** Build the first page query function for the given filters */
    private _buildFirstPage(
        filters: DeskFilters,
    ): () => QueryResponse<Booking> {
        const date = filters.date || Date.now();
        const period_start = addMinutes(startOfDay(date), this.tz_offset * 60);
        const period_end = addMinutes(endOfDay(date), this.tz_offset * 60);
        const active_zones = this._getActiveZones(filters.zones);
        const all_zones =
            !active_zones.length || filters.zones?.includes('All');
        const zones = all_zones
            ? this._settings.get('app.use_region')
                ? this._org.buildingsForRegion().map((_) => _.id)
                : [this._org.building.id]
            : active_zones;
        return () =>
            queryPagedBookings({
                period_start: getUnixTime(period_start),
                period_end: getUnixTime(period_end),
                type: 'desk',
                zones: zones.join(','),
                include_checked_out: true,
                include_deleted: true,
                limit: 200,
            });
    }

    /**
     * Load a page of desk bookings, either resetting the list or appending the
     * next page. Stale responses are discarded if a newer load has started.
     */
    private async _loadPage(reset: boolean) {
        const fetch = reset ? this._first_page : this._next_page_fn;
        if (!fetch) {
            if (reset) {
                this._bookings_state.set({
                    list: [],
                    total: 0,
                    has_next: false,
                });
                this._filters_changed.set(false);
            }
            return;
        }
        const token = ++this._load_token;
        this._loading.set(true);
        let failed = false;
        const resp = await Promise.resolve(fetch()).catch(() => {
            failed = true;
            return { data: [], total: 0, next: null };
        });
        if (token !== this._load_token) return;
        this._load_error.set(failed);
        const { data = [], total = 0, next = null } = resp || {};
        const list = data.map((booking) => this._normaliseBooking(booking));
        // Use the next link, not the total, to find more pages. staff-api
        // does not send a total for pages that expand recurring bookings.
        const has_next = list.length > 0 && !!next;
        this._next_page_fn = has_next ? next : null;
        this._bookings_state.update((acc) =>
            reset
                ? { list, total, has_next }
                : { list: [...acc.list, ...list], total, has_next },
        );
        if (reset) this._filters_changed.set(false);
        this._loading.set(false);
        this._last_updated.set(Date.now());
    }

    private _normaliseBooking(booking: Booking) {
        const status =
            this._booking_status()[this._bookingKey(booking)] ||
            (booking?.rejected ? 'declined' : '');
        if (!status) return booking;
        return new Booking({
            ...booking,
            approved: status === 'approved',
            rejected: status === 'declined',
            status,
        });
    }

    public setFilters(filters: DeskFilters) {
        if (filters.zones?.includes('All')) {
            filters.zones = [
                'All',
                ...this._org
                    .levelsForBuilding(this._org.building)
                    .map((lvl) => lvl.id),
            ];
        } else if (filters.zones && this._filters()?.zones?.includes('All')) {
            filters.zones = [];
        }
        // Set loading immediately when zones or date change to prevent stale data from showing
        if (filters.zones !== undefined || filters.date !== undefined) {
            this._loading.set(true);
            this._filters_changed.set(true);
        }
        this._filters.set({ ...this._filters(), ...filters });
    }

    public refresh() {
        this._loading.set(true);
        this._next_page_fn = this._first_page;
        this._loadPage(true);
    }

    /** Download the current desk list as a CSV file */
    public downloadDesksCSV() {
        const desks = this.desks();
        const rows = (
            desks.length
                ? desks
                : [
                      new Desk({
                          id: 'desk-123',
                          name: 'Test Desk',
                          bookable: true,
                          groups: ['test-desk-group', 'desk-bookers'],
                          features: ['Standing Desk', 'Dual Monitor'],
                          tags: ['engineering', 'level-3'],
                          homebase: 'Sydney HQ',
                      }),
                  ]
        ).map((desk) => {
            const row: any = desk.toJSON();
            delete row.images;
            return row;
        });
        downloadFile('desks.csv', jsonToCsv(rows));
    }

    /** Save the desks in CSV text. Rows without an `id` get a new one. */
    public importDesksCsv(csv: string) {
        const rows: Partial<Desk>[] = csvToJson(csv) || [];
        return this.addDesks(
            rows.map((row) => ({
                ...row,
                id: row.id || `desk-${randomInt(999_999)}`,
            })),
        );
    }

    /**
     * Save new or imported desks. Pass imported CSV rows as plain objects, not
     * `Desk` instances, so only the row's own columns update an existing desk.
     */
    public async addDesks(list: Partial<Desk>[]) {
        const selected_zones = this._getSelectedZones();
        const all_zones = this._filters().zones?.includes('All');
        const fallback_zone =
            !all_zones && selected_zones.length ? selected_zones[0] : '';
        // Group the desks by their level so each level's metadata is only
        // written with its own desks.
        const groups = new Map<string, Partial<Desk>[]>();
        for (const desk of list) {
            // imported rows carry the level as `zone_id`
            const zone = desk.zone?.id || desk['zone_id'] || fallback_zone;
            if (!zone) {
                notifyError(i18n('APP.CONCIERGE.DESKS_SELECT_LEVEL'));
                return;
            }
            groups.set(zone, [...(groups.get(zone) || []), desk]);
        }
        for (const [zone, desks] of groups) {
            if (this._settings.get('app.desks.use_assets')) {
                const asset_zones = this._deskAssetZones(zone);
                const existing = (
                    await queryDeskAssets(zone).catch(() => [])
                ).map((asset) => deskFromAsset(asset));
                await Promise.all(
                    desks.map((desk) =>
                        saveDeskAsset(
                            this._matchDeskAsset(desk, existing),
                            zone,
                            asset_zones,
                        ),
                    ),
                );
                continue;
            }
            const desk_list = await this._storedDeskList(zone);
            for (const row of desks) {
                const desk = row instanceof Desk ? row : new Desk(row);
                const idx = desk_list.findIndex((_) => _.id === desk.id);
                if (idx >= 0) desk_list[idx] = desk;
                else desk_list.push(desk);
            }
            await updateMetadata(zone, {
                name: 'desks',
                details: desk_list,
                description: 'List of available desks',
            });
        }
        this._change.set(Date.now());
    }

    /**
     * Imported rows update the desk asset with the same id, original desk id
     * (`place_id`) or map id rather than creating a duplicate. Migrated desk
     * assets keep the original desk id as their map id, or as `place_id` when
     * it differs. Columns missing from the row keep the asset's values.
     */
    private _matchDeskAsset(row: Partial<Desk>, existing: Desk[]): Desk {
        const match =
            findDeskByLegacyId(existing, row.id) ||
            findDeskByLegacyId(existing, row.map_id);
        if (!match) return new Desk(row);
        return new Desk({
            ...match,
            ...row,
            id: match.id,
            map_id: match.map_id,
            asset_type_id: match['asset_type_id'],
            client_ids: match['client_ids'],
            other_data: match['other_data'],
        } as Partial<Desk>);
    }

    /** Remove one desk from the configured resource store. */
    public async removeDesk(desk: Desk, zone_id: string) {
        if (this._settings.get('app.desks.use_assets')) {
            await deleteDeskAsset(desk.id);
        } else {
            const updated_desks = (await this._storedDeskList(zone_id)).filter(
                (_) => _.id !== desk.id,
            );
            await updateMetadata(zone_id, {
                name: 'desks',
                description: 'desks',
                details: updated_desks,
            });
        }
        this._change.set(Date.now());
    }

    /**
     * Open the desk modal and save the result. Moves the desk's assigned
     * booking when the assignee or ID changes, and rolls back the desk save
     * when that fails.
     */
    public async editDesk(desk: Desk = new Desk()) {
        const levels = this._currentLevelList();
        const zone_id =
            desk.zone?.id || this._getSelectedZones()[0] || levels[0]?.id || '';
        const ref = this._dialog.open(DeskModalComponent, {
            data: { desk, levels, zone_id },
        });
        const state = await deskModalResult(ref);
        if (state?.reason !== 'done') return;
        const { zone_id: selected_zone_id, ...desk_metadata } = state.metadata;
        const zone = desk.zone?.id || selected_zone_id || zone_id;
        if (!zone) {
            notifyError(i18n('APP.CONCIERGE.DESKS_SELECT_LEVEL'));
            return;
        }
        const use_assets = this._settings.get('app.desks.use_assets');
        const new_desk = this._editedDesk(
            desk,
            desk_metadata,
            zone,
            use_assets,
        );
        const original_desk_list = await this._levelDeskList(
            zone,
            use_assets,
        ).catch((e) => this._failDeskSave(ref, e));
        const desk_list = upsertDesk(original_desk_list, desk.id, new_desk);
        // Saving would store two desks with the same ID on this level. Desk
        // assets are identified by their map id, the asset id is generated.
        const desk_key = (item: Desk) =>
            use_assets ? item.map_id || item.id : item.id;
        const new_key = desk_key(new_desk);
        if (desk_list.filter((_) => desk_key(_) === new_key).length > 1) {
            notifyError(`A desk with the ID "${new_key}" already exists.`);
            ref.componentInstance.loading.set(false);
            ref.close();
            return;
        }
        if (new_desk.assigned_to && assignmentChanged(desk, new_desk)) {
            await this._checkAssignedDeskLimit(
                new_desk.assigned_to,
                desk.id,
            ).catch((error) => {
                notifyError(
                    error instanceof Error ? error.message : `${error}`,
                );
                ref.componentInstance.loading.set(false);
                ref.close();
                throw error;
            });
        }
        const saved_desk = await this._saveEditedDesk(
            new_desk,
            zone,
            desk_list,
            use_assets,
        ).catch((e) => this._failDeskSave(ref, e));
        const rollback = () =>
            this._rollbackDeskSave(zone, original_desk_list, desk, saved_desk);
        let recreate = false;
        if (desk.assigned_to && assignmentChanged(desk, saved_desk)) {
            await this._clearAssignedBooking(desk).catch(async (e) => {
                await rollback();
                return this._failDeskSave(ref, e);
            });
            recreate = true;
        }
        if (
            saved_desk.assigned_to &&
            (recreate || desk.assigned_to !== saved_desk.assigned_to)
        ) {
            await this._saveAssignedBooking(
                desk,
                saved_desk,
                zone,
                recreate,
                rollback,
            ).catch((e) =>
                this._failDeskSave(
                    ref,
                    e,
                    isConflict(e)
                        ? i18n('APP.CONCIERGE.DESKS_ASSIGN_CONFLICT_ERROR')
                        : undefined,
                ),
            );
        }
        this._change.set(Date.now());
        ref.close();
    }

    public async checkinDesk(desk: Booking, state = true) {
        if (!canChangeDeskBooking(this._normaliseBooking(desk))) return;
        const status = await setBookingCheckedIn(desk, state ?? true).catch(
            (_) => ({ failed: true, error: _ }),
        );
        if ('failed' in status) {
            notifyError(
                i18n(
                    state
                        ? 'APP.CONCIERGE.DESKS_CHECKIN_ERROR'
                        : 'APP.CONCIERGE.DESKS_CHECKOUT_ERROR',
                    { error: status.error },
                ),
            );
            throw status.error;
        }
        Object.assign(desk, {
            checked_in: status.checked_in,
            checked_in_at: status.checked_in_at,
            checked_out_at: status.checked_out_at,
            status: status.status,
        });
        notifySuccess(
            i18n(
                state
                    ? 'APP.CONCIERGE.DESKS_CHECKIN_SUCCESS'
                    : 'APP.CONCIERGE.DESKS_CHECKOUT_SUCCESS',
            ),
        );
    }

    public async approveDesk(desk: Booking) {
        if (!canChangeDeskBooking(this._normaliseBooking(desk))) return;
        const status: any = await approveBooking(desk.id).catch((_) => ({
            failed: true,
            error: _,
        }));
        if (status.failed) {
            return notifyError(
                i18n('APP.CONCIERGE.DESKS_APPROVE_ERROR', {
                    error: status.error,
                }),
            );
        }
        notifySuccess(i18n('APP.CONCIERGE.DESKS_APPROVE_SUCCESS'));
        (desk as any).approved = true;
        (desk as any).rejected = false;
        (desk as any).status = 'approved';
        this._setBookingStatus(desk, 'approved');
        this.setFilters({});
    }

    public async rejectDesk(desk: Booking) {
        if (!canChangeDeskBooking(this._normaliseBooking(desk))) return;
        const status: any = await this._rejectDeskBooking(desk).catch((_) => ({
            failed: true,
            error: _,
        }));
        if (status.failed) {
            return notifyError(
                i18n('APP.CONCIERGE.DESKS_REJECT_ERROR', {
                    error: status.error,
                }),
            );
        }
        notifySuccess(i18n('APP.CONCIERGE.DESKS_REJECT_SUCCESS'));
        (desk as any).approved = false;
        (desk as any).rejected = true;
        (desk as any).status = 'declined';
        this._setBookingStatus(desk, 'declined');
        this.setFilters({});
    }

    public async cancelBooking(booking: Booking, series = false) {
        if (isDeskBookingRejected(this._normaliseBooking(booking))) return;
        const result = await openConfirmModal(
            {
                title: i18n(
                    series
                        ? 'APP.CONCIERGE.DESKS_BOOKING_DELETE_SERIES_TITLE'
                        : 'APP.CONCIERGE.DESKS_BOOKING_DELETE_TITLE',
                ),
                content: i18n(
                    series
                        ? 'APP.CONCIERGE.DESKS_BOOKING_DELETE_SERIES_CONTENT'
                        : 'APP.CONCIERGE.DESKS_BOOKING_DELETE_CONTENT',
                    {
                        desk: booking.asset_name || booking.asset_id,
                        name: booking.user_name || booking.user_email,
                        date: format(booking.date, 'dd MMM yyyy'),
                    },
                ),
                icon: { content: 'event_busy' },
            },
            this._dialog,
        );
        if (result.reason !== 'done') return;
        result.loading(
            i18n(
                series
                    ? 'APP.CONCIERGE.DESKS_BOOKING_DELETE_SERIES_LOADING'
                    : 'APP.CONCIERGE.DESKS_BOOKING_DELETE_LOADING',
            ),
        );
        const query =
            !series && booking.instance
                ? { instance: true, start_time: booking.instance }
                : {};
        const booking_id = series
            ? booking.parent_id || booking.id
            : booking.id;
        await removeBooking(booking_id, query).catch((e) => {
            notifyError(
                i18n('APP.CONCIERGE.DESKS_BOOKING_DELETE_ERROR', { error: e }),
            );
            result.close();
            throw e;
        });
        notifySuccess(i18n('APP.CONCIERGE.DESKS_BOOKING_DELETE_SUCCESS'));
        result.close();
        this._bookings_state.update((state) => ({
            ...state,
            list: state.list.map((item) => {
                const is_deleted = series
                    ? item.id === booking_id || item.parent_id === booking_id
                    : this._bookingKey(item) === this._bookingKey(booking);
                return is_deleted
                    ? new Booking({
                          ...item,
                          deleted: true,
                          status: 'cancelled',
                      })
                    : item;
            }),
        }));
    }

    public viewBookingHistory(booking: Booking) {
        if (!booking) return;
        this._dialog.open(BookingHistoryModalComponent, {
            data: { booking },
            width: '32rem',
            maxWidth: '100vw',
        });
    }

    public async rejectAllDesks() {
        const search = this._filters().search;
        const list = this.bookings().filter(
            (desk) =>
                matchesDeskSearch(desk, search) &&
                canChangeDeskBooking(this._normaliseBooking(desk)),
        );
        if (list.length <= 0)
            return notifyInfo('No desks to reject for the selected date');
        const resp = await openConfirmModal(
            {
                title: i18n('APP.CONCIERGE.DESKS_REJECT_ALL_TITLE'),
                content: i18n('APP.CONCIERGE.DESKS_REJECT_ALL_MSG', {
                    count: list.length,
                }),
                icon: {
                    type: 'icon',
                    class: 'material-symbols-rounded',
                    content: 'delete',
                },
            },
            this._dialog,
        );
        if (resp.reason !== 'done') return;
        resp.loading(i18n('APP.CONCIERGE.DESKS_REJECT_ALL_LOADING'));
        try {
            await Promise.all(
                list.map((desk) => this._rejectDeskBooking(desk)),
            );
            list.forEach((desk) => {
                (desk as any).approved = false;
                (desk as any).rejected = true;
                (desk as any).status = 'declined';
                this._setBookingStatus(desk, 'declined');
            });
        } catch (e) {
            notifyError(
                i18n('APP.CONCIERGE.DESKS_REJECT_ALL_ERROR', { error: e }),
            );
            throw e;
        } finally {
            resp.close();
        }
        notifySuccess(i18n('APP.CONCIERGE.DESKS_REJECT_ALL_SUCCESS'));
        this.refresh();
    }

    /**
     * Approve or reject several bookings. Asks before it rejects.
     * @returns `false` if the user cancelled
     */
    public async setBookingsApproval(bookings: Booking[], approve: boolean) {
        const list = bookings.filter((desk) =>
            canChangeDeskBooking(this._normaliseBooking(desk)),
        );
        const failed = await runBulkAction(
            list,
            async (desk) => {
                await (approve
                    ? approveBooking(desk.id)
                    : this._rejectDeskBooking(desk));
                this._setBookingStatus(desk, approve ? 'approved' : 'declined');
            },
            approve ? {} : bulkRejectOptions(list.length, this._dialog),
        );
        if (failed === null) return false;
        this.refresh();
        return true;
    }

    private _rejectDeskBooking(desk: Booking) {
        return desk.instance
            ? rejectBookingInstance(desk.id, desk.instance)
            : rejectBooking(desk.id);
    }

    private _setBookingStatus(
        booking: Booking,
        status: 'approved' | 'declined',
    ) {
        this._booking_status.update((map) => ({
            ...map,
            [this._bookingKey(booking)]: status,
        }));
    }

    private _bookingKey(booking: Booking) {
        return `${booking.id}:${booking.instance || ''}`;
    }

    private async _checkAssignedDeskLimit(
        user_email: string,
        current_desk_id?: string,
    ) {
        const max_assigned_count = Math.max(
            Number(this._settings.get('app.desks.max_assigned_count')) || 0,
            0,
        );
        if (!max_assigned_count || !user_email) return;
        const email = user_email.toLowerCase();
        const levels = this._currentLevelList();
        const desks = this._settings.get('app.desks.use_assets')
            ? await queryDeskAssetsInZone(this._currentScopeId())
            : (
                  await Promise.all(
                      levels.map((level) =>
                          showMetadata(level.id, 'desks')
                              .then((metadata) =>
                                  metadata.details instanceof Array
                                      ? metadata.details
                                      : [],
                              )
                              .catch(() => []),
                      ),
                  )
              ).flat();
        const assigned_count = desks.filter(
            (item: Partial<Desk>) =>
                item.id !== current_desk_id &&
                item.assigned_to?.toLowerCase() === email,
        ).length;
        if (assigned_count >= max_assigned_count) {
            const key = 'APP.CONCIERGE.DESKS_ASSIGN_LIMIT_ERROR';
            const message = i18n(
                key,
                { count: max_assigned_count },
                max_assigned_count,
            );
            throw !message || message === key
                ? `Users can only have ${max_assigned_count} assigned desk${max_assigned_count === 1 ? '' : 's'} at a time.`
                : message;
        }
    }

    /**
     * Read the desk list stored in a zone's metadata. Errors are not caught,
     * so callers never write a list built from a failed read.
     */
    private async _storedDeskList(zone: string): Promise<Desk[]> {
        const { details } = await showMetadata(zone, 'desks');
        return (details instanceof Array ? details : []).map(
            (item) => new Desk({ ...item, zone: { id: zone } }),
        );
    }

    /**
     * Build the desk to save from the modal values. Asset desks keep their
     * stored fields and ID. New desks without an ID get a random one.
     */
    private _editedDesk(
        desk: Desk,
        metadata: Partial<Desk>,
        zone: string,
        use_assets: boolean,
    ): Desk {
        return new Desk({
            ...(use_assets ? desk : {}),
            ...metadata,
            id:
                (use_assets && desk['asset_type_id'] ? desk.id : metadata.id) ||
                `desk-${zone.slice(-3)}.${randomInt(999_999)}`,
            // Desks store the level as their zone. Desk types its zone as a
            // PlaceZone, which BuildingLevel does not match.
            zone: this._org.levelWithID([zone]) as unknown as PlaceZone,
        });
    }

    /**
     * Desks currently on a level. Only this level is written on save, so for
     * metadata the stored list is read to keep desks that are not loaded in
     * the current view.
     */
    private async _levelDeskList(
        zone: string,
        use_assets: boolean,
    ): Promise<Desk[]> {
        return use_assets
            ? this.desks().filter((_) => (_.zone?.id || zone) === zone)
            : this._storedDeskList(zone);
    }

    /**
     * Write an edited desk. Asset desks are saved one at a time. Metadata
     * desks are saved as the level's full `desk_list`.
     * @returns The desk as stored
     */
    private async _saveEditedDesk(
        desk: Desk,
        zone: string,
        desk_list: Desk[],
        use_assets: boolean,
    ): Promise<Desk> {
        if (use_assets) {
            const saved = await saveDeskAsset(
                desk,
                zone,
                this._deskAssetZones(zone),
            );
            return deskFromAsset(saved, this._org.levelWithID([zone]));
        }
        await updateMetadata(zone, {
            name: 'desks',
            details: desk_list,
            description: 'List of available desks',
        });
        return desk;
    }

    /**
     * Create the assigned booking for a saved desk and cancel the assignee's
     * overlapping desk bookings. On failure, roll back the desk save, restore
     * the previous assigned booking when it was cleared, and rethrow.
     */
    private async _saveAssignedBooking(
        previous: Desk,
        desk: Desk,
        zone: string,
        restore_previous: boolean,
        rollback: () => Promise<void>,
    ) {
        const created = await saveBooking(
            this._createAssignedBooking(desk, zone).toJSON(),
        ).catch(async (e) => {
            await rollback();
            if (restore_previous) {
                await this._restoreAssignedBooking(previous, zone).catch(
                    (restore_err) =>
                        console.error(
                            'Failed to restore assigned booking during rollback',
                            restore_err,
                        ),
                );
            }
            throw e;
        });
        // Cancel the assignee's overlapping ad-hoc desk bookings over the
        // next 4 weeks so a later approval cannot reactivate them.
        if (created?.id) {
            await cancelOverlappingRecurringBookings(created, 'desk').catch(
                () => [],
            );
        }
    }

    /** Show a desk save error, stop the modal's loading state, and rethrow. */
    private _failDeskSave(
        ref: MatDialogRef<DeskModalComponent>,
        error: unknown,
        message = i18n('APP.CONCIERGE.DESKS_SAVE_ERROR', { error }),
    ): never {
        notifyError(message);
        ref.componentInstance.loading.set(false);
        throw error;
    }

    private async _rollbackDeskSave(
        zone: string,
        original_desk_list: Desk[],
        original_desk: Desk,
        saved_desk: Desk,
    ) {
        if (!this._settings.get('app.desks.use_assets')) {
            return this._rollbackMetadata(zone, original_desk_list);
        }
        try {
            if (original_desk['asset_type_id']) {
                await saveDeskAsset(
                    original_desk,
                    zone,
                    this._deskAssetZones(zone),
                );
            } else if (saved_desk.id) {
                await deleteDeskAsset(saved_desk.id);
            }
        } catch (rollback_err) {
            console.error(
                'Failed to rollback desk asset after error',
                rollback_err,
            );
        }
    }

    private async _rollbackMetadata(
        zone: string,
        original_desk_list: unknown[],
    ) {
        try {
            await updateMetadata(zone, {
                name: 'desks',
                details: original_desk_list,
                description: 'List of available desks',
            });
        } catch (rollback_err) {
            console.error(
                'Failed to rollback desk metadata after error',
                rollback_err,
            );
        }
    }

    /** Build the complete zone path required for asset scope queries. */
    private _deskAssetZones(level_id: string) {
        return assetZones(this._org, level_id);
    }

    private _createAssignedBooking(desk: Desk, zone?: string) {
        const timezone = this._settings.get(
            'app.bookings.use_building_timezone',
        )
            ? this._org.building?.timezone
            : '';
        const date = setTimeInTimezone(Date.now(), 1, 0, timezone);
        return new Booking({
            user_id: desk.assigned_to,
            user_email: desk.assigned_to,
            user_name: desk['assigned_name'],
            booking_start: getUnixTime(date),
            booking_end: getUnixTime(addHours(date, 22)),
            type: 'desk',
            booking_type: 'desk',
            asset_id: desk.id,
            asset_name: desk.name,
            recurrence_type: 'daily',
            recurrence_days:
                RecurrenceDays.MONDAY |
                RecurrenceDays.TUESDAY |
                RecurrenceDays.WEDNESDAY |
                RecurrenceDays.THURSDAY |
                RecurrenceDays.FRIDAY |
                RecurrenceDays.SATURDAY |
                RecurrenceDays.SUNDAY,
            zones: unique([
                this._org.organisation.id,
                this._org.region?.id,
                this._org.building?.id,
                desk.zone?.id,
                desk.zone,
                ...(desk['zones'] || []),
                zone,
            ]).filter((_) => !!_),
            extension_data: {
                asset_name: desk.name,
                is_assigned: true,
            },
        });
    }

    private async _restoreAssignedBooking(desk: Desk, zone?: string) {
        if (!desk.assigned_to) return;
        await saveBooking(this._createAssignedBooking(desk, zone).toJSON());
    }

    private async _clearAssignedBooking(desk: Desk) {
        const today = Date.now();
        const booking_list = await queryBookings({
            period_start: getUnixTime(startOfDay(today)),
            period_end: getUnixTime(endOfDay(today)),
            type: 'desk',
            email: desk.assigned_to,
            include_checked_out: true,
        });
        const filtered = booking_list.filter((_) => _.asset_id === desk.id);
        const today_start = getUnixTime(startOfDay(today));
        for (const booking of filtered) {
            const is_recurring = booking.instance;
            const series_starts_today =
                getUnixTime(startOfDay(booking.booking_start * 1000)) ===
                today_start;
            if (is_recurring && !series_starts_today) {
                const yesterday_end = getUnixTime(endOfDay(subDays(today, 1)));
                await updateBooking(
                    booking.id,
                    { recurrence_end: yesterday_end },
                    'patch',
                );
            } else {
                // Series starts today (truncating to yesterday would be
                // invalid) or it is a one-off booking, so delete it outright.
                await removeBooking(booking.parent_id || booking.id);
            }
        }
    }

    /** Selected zone filters with the "all levels" sentinel keys stripped */
    private _getSelectedZones(): string[] {
        return (this._filters().zones || []).filter(
            (zone) => !this._all_zones_keys.includes(zone),
        );
    }

    private _getActiveZones(zones: string[] = []): string[] {
        const level_list = this._currentLevelList();
        const level_ids = new Set(level_list.map((level) => level.id));
        return (zones || []).filter(
            (zone) =>
                !this._all_zones_keys.includes(zone) && level_ids.has(zone),
        );
    }

    /** The building, or region with `use_region`, that the level list covers */
    private _currentScopeId(): string {
        return this._settings.get('app.use_region')
            ? this._org.region?.id || ''
            : this._org.building?.id || '';
    }

    private _currentLevelList(): BuildingLevel[] {
        return this._settings.get('app.use_region')
            ? this._org.levelsForRegion(this._org.region)
            : this._org.levelsForBuilding(this._org.building);
    }
}
